package io.github.benbagwell.dominoprint.render;

import io.github.benbagwell.dominoprint.formula.*;
import io.github.benbagwell.dominoprint.model.*;
import org.junit.jupiter.api.Test;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;

class PrintPipelineTest {
    final FormulaEngine engine=new FormulaEngine();final PrintFormCompiler compiler=new PrintFormCompiler(engine);
    final PrintCache.Scope scope=new PrintCache.Scope("server/apps.nsf","CN=Loader/O=Acme");
    final DocumentSnapshot document=new DxlDocumentReader().read("""
        <document form="Data"><noteinfo unid="00000000000000000000000000000001" sequence="1"/><item name="Status"><text>A</text></item><item name="Quantity"><number>3</number></item><item name="Price"><number>12.5</number></item><item name="Saved"><text>stored</text></item><item name="Body"><richtext><par><run><font style="bold"/>Rich body</run></par></richtext></item></document>
        """);
    String form(String body){return "<form name='Print' alias='PrintAlias'><noteinfo unid='F' sequence='2'/><body><richtext>"+body+"</richtext></body></form>";}
    PrintCache.Bundle bundle(String body,String label){var translations=new CodeTranslations(Map.of("Status",Map.of("A",FormulaValue.text(label))),false);return new PrintCache.Bundle(scope,List.of(compiler.compile(form(body))),translations,SnapshotLookups.empty(translations),Map.of(),Map.of(),Map.of("forms","v1"));}
    PrintCache cache(String body){var cache=new PrintCache(scope);cache.refresh(()->bundle(body,"Approved"));return cache;}
    @Test void computesTranslationsAndBothOutputsFromOneTree(){
        String body="""
            <pardef id="1" align="center"/><pardef id="2"><code event="hidewhen"><formula>Status != "A"</formula></code></pardef>
            <par def="1"><run><font size="18pt" style="bold"/>Invoice</run></par>
            <par def="2">Status: <field name="Label" type="text" kind="computedfordisplay"><code event="value"><formula>@Translate("Status";Status)</formula></code></field></par>
            <table><tablerow><tablecell><par>Total</par></tablecell><tablecell><par><field name="Total" type="number" kind="computedfordisplay"><numberformat format="fixed" digits="2"/><code event="value"><formula>Quantity * Price</formula></code></field></par></tablecell></tablerow></table>
            <par><field name="Body" type="richtext"/></par>
            """;
        var result=new PrintRenderer(engine).render(cache(body),"PrintAlias",document);
        assertTrue(result.plainText().contains("Status: Approved"),result.plainText());assertTrue(result.plainText().contains("37.50"));assertTrue(result.plainText().contains("Rich body"));assertTrue(result.html().contains("text-align:center"));assertTrue(result.html().contains("font-weight:bold"));assertEquals(37.5,result.workingFields().get("total").number());assertEquals(1,result.cacheVersion());assertEquals("F:2",result.formVersion());assertTrue(document.item("Total").isEmpty());
    }
    @Test void computesHiddenFieldsButSuppressesTheirLayout(){var cache=cache("<pardef id='1' hide='web'/><par def='1'><field name='Hidden' type='text' kind='computedfordisplay'><code event='value'><formula>\"secret\"</formula></code></field></par><par><computedtext><code event='value'><formula>Hidden + \" shown\"</formula></code></computedtext></par>");var result=new PrintRenderer(engine).render(cache,"Print",document);assertEquals("secret shown\n",result.plainText());}
    @Test void preservesSavedComputedAndWhenComposedFields(){var cache=cache("<par><field name='Saved' type='text' kind='computed'><code event='value'><formula>\"recomputed\"</formula></code></field><field name='Old' type='text' kind='computedwhencomposed'><code event='value'><formula>\"new\"</formula></code></field></par>");var result=new PrintRenderer(engine).render(cache,"Print",document);assertEquals("stored\n",result.plainText());assertFalse(result.workingFields().containsKey("old"));}
    @Test void missingComputedFieldsOnAlternatePrintFormsAreEvaluated(){var cache=cache("<par><field name='NotStored' type='text' kind='computed'><code event='value'><formula>Status</formula></code></field></par>");assertEquals("A\n",new PrintRenderer(engine).render(cache,"Print",document).plainText());}
    @Test void htmlEscapesDocumentValues(){var doc=new DocumentSnapshot(Map.of(),List.of(ItemSnapshot.text("Unsafe","<script>alert('x')</script>")),"","",List.of());var result=new PrintRenderer(engine).render(cache("<par><field name='Unsafe' type='text'/></par>"),"Print",doc);assertFalse(result.html().contains("<script>"));assertTrue(result.html().contains("&lt;script&gt;"));assertTrue(result.plainText().contains("<script>"));}
    @Test void failedRefreshRetainsPreviousVersion(){var cache=cache("<par>good</par>");var prior=cache.snapshot();assertThrows(IllegalArgumentException.class,()->cache.refresh(()->bundle("<par><computedtext><code event='value'><formula>@Unknown</formula></code></computedtext></par>","bad")));assertSame(prior,cache.snapshot());}
    @Test void cacheRejectsDifferentIdentity(){var cache=cache("<par>good</par>");var candidate=bundle("<par>bad</par>","bad");assertThrows(IllegalArgumentException.class,()->cache.refresh(()->new PrintCache.Bundle(new PrintCache.Scope("other","other"),candidate.forms(),candidate.codes(),candidate.lookups(),Map.of(),Map.of(),Map.of())));}
    @Test void detectsScriptsAndRequiresPreparationHook(){var source="<form name='Print'><code event='webqueryopen'><formula>@Command([ToolsRunMacro];\"Prepare\")</formula></code><body><richtext><par><field name='Prepared' type='text'/></par></richtext></body></form>";var form=compiler.compile(source);assertEquals(Set.of("Print:webqueryopen"),form.preparationDependencies());var cache=new PrintCache(scope);assertThrows(IllegalArgumentException.class,()->cache.refresh(()->new PrintCache.Bundle(scope,List.of(form),CodeTranslations.empty(),SnapshotLookups.empty(CodeTranslations.empty()),Map.of(),Map.of(),Map.of())));cache.refresh(()->new PrintCache.Bundle(scope,List.of(form),CodeTranslations.empty(),SnapshotLookups.empty(CodeTranslations.empty()),Map.of(),Map.of("Print:webqueryopen",(fields,context)->{var copy=new HashMap<>(fields);copy.put("Prepared",FormulaValue.text("ported"));return copy;}),Map.of()));assertEquals("ported\n",new PrintRenderer(engine).render(cache,"Print",document).plainText());}
    @Test void staticAndComputedSubformsHaveIndependentParagraphDefinitions(){var print=compiler.compile(form("<pardef id='1' align='left'/><par def='1'>main</par><subformref name='Part'/><subformref><code event='subform'><formula>\"Part\"</formula></code></subformref>"));var sub=compiler.compile("<subform name='Part'><body><richtext><pardef id='1' align='right'/><par def='1'>sub</par></richtext></body></subform>");var cache=new PrintCache(scope);cache.refresh(()->new PrintCache.Bundle(scope,List.of(print,sub),CodeTranslations.empty(),SnapshotLookups.empty(CodeTranslations.empty()),Map.of(),Map.of(),Map.of()));var result=new PrintRenderer(engine).render(cache,"Print",document);assertEquals("main\nsub\nsub\n",result.plainText());assertTrue(result.html().contains("text-align:right"));}
    @Test void recursionAndMissingStaticResourcesBlockCachePublication(){var sub=compiler.compile("<subform name='Loop'><body><richtext><subformref name='Loop'/></richtext></body></subform>");var print=compiler.compile(form("<subformref name='Loop'/>"));var cache=new PrintCache(scope);assertThrows(IllegalArgumentException.class,()->cache.refresh(()->new PrintCache.Bundle(scope,List.of(print,sub),CodeTranslations.empty(),SnapshotLookups.empty(CodeTranslations.empty()),Map.of(),Map.of(),Map.of())));}
    @Test void dataRichTextUnknownFeaturesDoNotSilentlyDisappear(){var doc=new DxlDocumentReader().read("<document><item name='Body'><richtext><par><objectref name='OLE'/></par></richtext></item></document>");assertThrows(RenderException.class,()->new PrintRenderer(engine).render(cache("<par><field name='Body' type='richtext'/></par>"),"Print",doc));}
    @Test void includesImageResourceWithoutExternalRequests(){var compiled=compiler.compile(form("<par><picture alttext='logo' width='12px'><imageref name='logo.png'/></picture></par>"));var image=new BinaryContent("logo.png","image/png",new byte[]{1,2,3});var cache=new PrintCache(scope);cache.refresh(()->new PrintCache.Bundle(scope,List.of(compiled),CodeTranslations.empty(),SnapshotLookups.empty(CodeTranslations.empty()),Map.of("logo.png",image),Map.of(),Map.of()));var result=new PrintRenderer(engine).render(cache,"Print",document);assertTrue(result.html().contains("data:image/png;base64,AQID"));assertEquals(1,result.assets().size());}
    @Test void concurrentRefreshNeverMixesTranslationVersions()throws Exception{
        String body="<par><computedtext><code event='value'><formula>@Translate(\"Status\";Status)</formula></code></computedtext>/<computedtext><code event='value'><formula>@Translate(\"Status\";Status)</formula></code></computedtext></par>";var cache=cache(body);var renderer=new PrintRenderer(engine);var pool=Executors.newFixedThreadPool(8);
        try{List<Callable<Void>> tasks=new ArrayList<>();for(int n=0;n<300;n++)tasks.add(()->{var result=renderer.render(cache,"Print",document);String text=result.plainText().trim();var parts=text.split("/");assertEquals(parts[0],parts[1]);return null;});tasks.add(()->{for(int i=0;i<30;i++){String label="V"+i;cache.refresh(()->bundle(body,label));}return null;});for(var f:pool.invokeAll(tasks))f.get();}finally{pool.shutdownNow();}
    }
    @Test void keywordAliasesDisplayLabels(){var result=new PrintRenderer(engine).render(cache("<par><field name='Status' type='text'><keywords><textlist><text>Approved|A</text><text>Declined|D</text></textlist></keywords></field></par>"),"Print",document);assertEquals("Approved\n",result.plainText());}
    @Test void dangerousLinksAndRawHtmlAttributesAreExplicitlyRejected(){assertFalse(compiler.compile(form("<par htmlstyle='width:expression(x)'>x</par>")).structurallySupported());assertThrows(RenderException.class,()->new PrintRenderer(engine).render(cache("<par><urllink href='javascript:alert(1)'>click</urllink></par>"),"Print",document));}
}
